/**
 * Tests on the MNIST dataset.
 */
@Test
public void testMNIST() throws IOException {
    int featCnt = 28 * 28;
    int hiddenNeuronsCnt = 100;
    Map<Integer, MnistUtils.MnistLabeledImage> trainingSet = new HashMap<>();
    int i = 0;
    for (MnistUtils.MnistLabeledImage e : MnistMLPTestUtil.loadTrainingSet(60_000)) trainingSet.put(i++, e);
    MLPArchitecture arch = new MLPArchitecture(featCnt).withAddedLayer(hiddenNeuronsCnt, true, Activators.SIGMOID).withAddedLayer(10, false, Activators.SIGMOID);
    MLPTrainer<?> trainer = new MLPTrainer<>(arch, LossFunctions.MSE, new UpdatesStrategy<>(new RPropUpdateCalculator(), RPropParameterUpdate::sum, RPropParameterUpdate::avg), 200, 2000, 10, 123L);
    System.out.println("Start training...");
    long start = System.currentTimeMillis();
    MultilayerPerceptron mdl = trainer.fit(trainingSet, 1, (k, v) -> VectorUtils.of(v.getPixels()), (k, v) -> VectorUtils.num2Vec(v.getLabel(), 10).getStorage().data());
    System.out.println("Training completed in " + (System.currentTimeMillis() - start) + "ms");
    int correctAnswers = 0;
    int incorrectAnswers = 0;
    for (MnistUtils.MnistLabeledImage e : MnistMLPTestUtil.loadTestSet(10_000)) {
        Matrix input = new DenseMatrix(new double[][] { e.getPixels() });
        Matrix outputMatrix = mdl.apply(input);
        int predicted = (int) VectorUtils.vec2Num(outputMatrix.getRow(0));
        if (predicted == e.getLabel())
            correctAnswers++;
        else
            incorrectAnswers++;
    }
    double accuracy = 1.0 * correctAnswers / (correctAnswers + incorrectAnswers);
    assertTrue("Accuracy should be >= 80% (not " + accuracy * 100 + "%)", accuracy >= 0.8);
}

