/**
 * Tests on the MNIST dataset. For manual run.
 */
@Test
public void testMNIST() throws IOException {
    Map<Integer, MnistUtils.MnistLabeledImage> trainingSet = new HashMap<>();
    int i = 0;
    for (MnistUtils.MnistLabeledImage e : MnistMLPTestUtil.loadTrainingSet(60_000)) trainingSet.put(i++, e);
    DecisionTreeClassificationTrainer trainer = new DecisionTreeClassificationTrainer(8, 0, new SimpleStepFunctionCompressor<>());
    DecisionTreeNode mdl = trainer.fit(trainingSet, 10, (k, v) -> VectorUtils.of(v.getPixels()), (k, v) -> (double) v.getLabel());
    int correctAnswers = 0;
    int incorrectAnswers = 0;
    for (MnistUtils.MnistLabeledImage e : MnistMLPTestUtil.loadTestSet(10_000)) {
        double res = mdl.apply(new DenseVector(e.getPixels()));
        if (res == e.getLabel())
            correctAnswers++;
        else
            incorrectAnswers++;
    }
    double accuracy = 1.0 * correctAnswers / (correctAnswers + incorrectAnswers);
    assertTrue(accuracy > 0.8);
}

/**
 */
@Test
public void testFit() {
    int sampleSize = 1000;
    Map<double[], Double> sample = new HashMap<>();
    for (int i = 0; i < sampleSize; i++) {
        double x1 = i;
        double x2 = x1 / 10.0;
        double x3 = x2 / 10.0;
        double x4 = x3 / 10.0;
        sample.put(new double[] { x1, x2, x3, x4 }, (double) (i % 2));
    }
    RandomForestClassifierTrainer trainer = new RandomForestClassifierTrainer(4, 3, 5, 0.3, 4, 0.1).withUseIndex(false);
    ModelsComposition mdl = trainer.fit(sample, parts, (k, v) -> VectorUtils.of(k), (k, v) -> v);
    mdl.getModels().forEach(m -> {
        assertTrue(m instanceof ModelOnFeaturesSubspace);
        ModelOnFeaturesSubspace mdlOnFeaturesSubspace = (ModelOnFeaturesSubspace) m;
        assertTrue(mdlOnFeaturesSubspace.getMdl() instanceof DecisionTreeConditionalNode);
        assertTrue(mdlOnFeaturesSubspace.getFeaturesMapping().size() > 0);
        String expClsName = "ModelOnFeatureSubspace";
        assertTrue(mdlOnFeaturesSubspace.toString().contains(expClsName));
        assertTrue(mdlOnFeaturesSubspace.toString(true).contains(expClsName));
        assertTrue(mdlOnFeaturesSubspace.toString(false).contains(expClsName));
    });
    assertTrue(mdl.getPredictionsAggregator() instanceof OnMajorityPredictionsAggregator);
    assertEquals(5, mdl.getModels().size());
}

/**
 */
@Test
public void testFit() {
    int sampleSize = 1000;
    Map<Double, double[]> sample = new HashMap<>();
    for (int i = 0; i < sampleSize; i++) {
        double x1 = i;
        double x2 = x1 / 10.0;
        double x3 = x2 / 10.0;
        double x4 = x3 / 10.0;
        sample.put(x1 * x2 + x3 * x4, new double[] { x1, x2, x3, x4 });
    }
    RandomForestRegressionTrainer trainer = new RandomForestRegressionTrainer(4, 3, 5, 0.3, 4, 0.1).withUseIndex(false);
    ModelsComposition mdl = trainer.fit(sample, parts, (k, v) -> VectorUtils.of(v), (k, v) -> k);
    mdl.getModels().forEach(m -> {
        assertTrue(m instanceof ModelOnFeaturesSubspace);
        assertTrue(((ModelOnFeaturesSubspace) m).getMdl() instanceof DecisionTreeConditionalNode);
    });
    assertTrue(mdl.getPredictionsAggregator() instanceof MeanValuePredictionsAggregator);
    assertEquals(5, mdl.getModels().size());
}

/**
 * @throws Exception
 */
@Test
public void testAllBundlesActiveAndFeaturesInstalled() throws Exception {
    // Asssert all bundles except fragments are ACTIVE.
    for (Bundle b : bundleCtx.getBundles()) {
        System.out.println(String.format("Checking state of bundle [symbolicName=%s, state=%s]", b.getSymbolicName(), b.getState()));
        if (b.getHeaders().get(Constants.FRAGMENT_HOST) == null)
            assertTrue(b.getState() == Bundle.ACTIVE);
    }
    // Check that according to the FeaturesService, all Ignite features except ignite-log4j are installed.
    Feature[] features = featuresSvc.getFeatures(IGNITE_FEATURES_NAME_REGEX);
    assertNotNull(features);
    assertEquals(EXPECTED_FEATURES, features.length);
    for (Feature f : features) {
        if (IGNORED_FEATURES.contains(f.getName()))
            continue;
        boolean installed = featuresSvc.isInstalled(f);
        System.out.println(String.format("Checking if feature is installed [featureName=%s, installed=%s]", f.getName(), installed));
        assertTrue(installed);
        assertEquals(PROJECT_VERSION.replaceAll("-", "."), f.getVersion().replaceAll("-", "."));
    }
}

